const dmErrMsg = String(e?.message ?? e)
// ⭐ 深鲸补丁（2026-11-06 中午）：出错要留账 —— 原来只写一句「已兜住」，一整天 32 条，谁也没看见
try {
  const r = nextDmBackoff(dmBackoff || (dmBackoff = loadDmBackoff()), dmErrMsg, Date.now())
  dmBackoff = r.state
  writeJsonFile(dmBackoffFile, dmBackoff)
  log(`私信监查出错（已兜住）：${dmErrMsg} ⇒ 退避 ${Math.max(1, Math.round(r.waitMs / 60000))} 分钟（连败 ${r.fails} 次）`)
  if (r.alarm) appendDmAlarm(r.state)
} catch (e2) {
  log('私信监查出错（已兜住）：' + dmErrMsg)
}
